#include <iostream>

int preparar(int semilla) {
    std::cout << "Preparar:" << semilla << ';';
    return semilla + 1;
}

int conservar(int semilla) {
    if (semilla < 0) {
        return -1;
    }
    static int base = preparar(semilla);
    return base;
}

int main() {
    const int omitido = conservar(-2);

    std::cout << omitido << ':';
    const int primero = conservar(4);
    std::cout << primero << ':';
    const int segundo = conservar(9);
    std::cout << segundo;

    return 0;
}

