#include <iostream>

int preparar(int semilla) {
    std::cout << "Intento:" << semilla << ';';
    if (semilla < 0) {
        throw std::runtime_error("Sin base");
    }

    return semilla + 1;
}

int conservar(int semilla) {
    static int base = preparar(semilla);
    return base;
}

int main() {
    try {
        conservar(-1);
    } catch (const std::exception& error) {
        std::cout << error.what() << ';';
    }
    const int primero = conservar(4);
    std::cout << "Valor:" << primero << ';';
    const int segundo = conservar(9);
    std::cout << "Final:" << segundo;

    return 0;
}

