#include <iostream>

int gestionar(int orden, int cantidad) {
    // Conserva aqui un unico total entre llamadas.
    // Aplica el contrato de consultar, sumar o reiniciar.
    // Devuelve -1 al rechazar y conserva el total anterior.
    if (orden == 0) {
        return 0;
    }

    return cantidad;
}

int main() {
    int numeroDeOrdenes = 0;
    if (!(std::cin >> numeroDeOrdenes) ||
        numeroDeOrdenes < 1 || numeroDeOrdenes > 15) {
        std::cout << "Datos invalidos\n";
        return 0;
    }
    for (int i = 0; i < numeroDeOrdenes; ++i) {
        int orden = 0;
        int cantidad = 0;

        if (!(std::cin >> orden >> cantidad)) {
            std::cout << "Datos invalidos\n";
            return 0;
        }
        const int respuesta = gestionar(orden, cantidad);
        const int totalActual = gestionar(0, 0);

        if (respuesta == -1) {
            std::cout << "Rechazo";
        } else {
            std::cout << "Aceptado:" << respuesta;
        }
        std::cout << ";Total:" << totalActual << '\n';
    }

    return 0;
}

